import React, { Component } from 'react';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CTextarea,
    CRow
} from '@coreui/react';
import Select from 'react-select';
import { Logger } from '../../Utils/Utils';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { reloadPage } from '../../Utils/Utils';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "CreateAction.js";

const PRIORITY_OPTIONS = [
    { value: 'P0', label: 'P0 — highest' },
    { value: 'P1', label: 'P1 — medium' },
    { value: 'P2', label: 'P2 — lowest' },
];

const STATUS_OPTIONS = [
    { value: 'TODO', label: 'TODO' },
    { value: 'WIP', label: 'WIP' },
    { value: 'DONE', label: 'DONE' },
];

class CreateAction extends Component {

    constructor(props) {
        super(props);
        this.state = {
            title: '',
            description: '',
            priority: 'P1',
            status: 'TODO',
            programId: '',
            personId: '',
            dueDate: '',
            comments: [],       // [{ comment }]
            newComment: '',
            programs: [],
            persons: [],
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Create Action";
        this.fetchReferenceData();
    }

    fetchReferenceData = () => {
        const userData = getUserDataFromLocalStorage();
        const programPayload = JSON.stringify({ page: 1, size: 0 });
        const personPayload = JSON.stringify({ page: 1, size: 0 });

        Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list', requestHeaderPOSTWithAuth(personPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([programsResult, personsResult]) => {
            this.setState({
                programs: (programsResult && programsResult.data) || [],
                persons: (personsResult && personsResult.data) || [],
            });
        })
        .catch(error => Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error));
    }

    addComment = () => {
        const text = this.state.newComment.trim();
        if (!text) return;
        this.setState(prev => ({ comments: [...prev.comments, { comment: text }], newComment: '' }));
    }

    removeComment = (index) => {
        this.setState(prev => ({ comments: prev.comments.filter((_, i) => i !== index) }));
    }

    handleSubmit = (e) => {
        e.preventDefault();

        const { title, description, priority, status, programId, personId, dueDate, comments } = this.state;

        if (!title.trim()) {
            alert('Title is required.');
            return;
        }
        if (!priority) {
            alert('Priority is required.');
            return;
        }

        const payload = {
            title: title.trim(),
            description: description.trim() || null,
            priority,
            status: status || 'TODO',
            programId: programId ? Number(programId) : null,
            personId: personId ? Number(personId) : null,
            dueDate: dueDate || null,
            comments: comments.length > 0 ? comments : null,
        };

        Logger(FILE_NAME, "handleSubmit", "", "payload", payload);
        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/action';

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleSubmit", "SUCCESS", "result", result);
            const createdId = result && result.data && result.data.id;
            this.setState({ loadingModalState: 1 });
            setTimeout(() => {
                this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                if (createdId) {
                    window.location.hash = '#/actions/' + createdId;
                } else {
                    this.resetForm();
                }
            }, 700);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    resetForm = () => {
        this.setState({
            title: '',
            description: '',
            priority: 'P1',
            status: 'TODO',
            programId: '',
            personId: '',
            dueDate: '',
            comments: [],
            newComment: '',
        });
    }

    render() {
        const { title, description, priority, status, programId, personId, dueDate, comments, newComment, programs, persons } = this.state;

        const programOptions = programs.map(p => ({ value: String(p.id), label: `${p.name}${p.type ? ' (' + p.type + ')' : ''}` }));
        const personOptions = persons.map(p => ({ value: String(p.id), label: p.name }));

        return (
            <div>
                <a href="#/actions" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Actions List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="8">
                            <CCardGroup>
                                <CCard className="p-4">
                                    <CCardBody>
                                        <CForm onSubmit={this.handleSubmit}>
                                            <h1>✅ Create Action</h1>
                                            <br />

                                            <label><strong>Title *</strong></label>
                                            <CInput
                                                className="mb-3"
                                                placeholder="What needs to be done?"
                                                value={title}
                                                onChange={(e) => this.setState({ title: e.target.value })}
                                                required
                                            />

                                            <label><strong>Description</strong></label>
                                            <CTextarea
                                                className="mb-3"
                                                rows="3"
                                                placeholder="More detail (optional)"
                                                value={description}
                                                onChange={(e) => this.setState({ description: e.target.value })}
                                            />

                                            <CRow>
                                                <CCol md="6">
                                                    <label><strong>Priority *</strong></label>
                                                    <Select
                                                        className="mb-3"
                                                        options={PRIORITY_OPTIONS}
                                                        value={PRIORITY_OPTIONS.find(o => o.value === priority) || null}
                                                        onChange={(opt) => this.setState({ priority: opt ? opt.value : '' })}
                                                    />
                                                </CCol>
                                                <CCol md="6">
                                                    <label><strong>Status</strong></label>
                                                    <Select
                                                        className="mb-3"
                                                        options={STATUS_OPTIONS}
                                                        value={STATUS_OPTIONS.find(o => o.value === status) || null}
                                                        onChange={(opt) => this.setState({ status: opt ? opt.value : 'TODO' })}
                                                    />
                                                </CCol>
                                            </CRow>

                                            <CRow>
                                                <CCol md="6">
                                                    <label><strong>Program</strong></label>
                                                    <Select
                                                        className="mb-3"
                                                        isClearable
                                                        placeholder="Optional"
                                                        options={programOptions}
                                                        value={programOptions.find(o => o.value === String(programId)) || null}
                                                        onChange={(opt) => this.setState({ programId: opt ? opt.value : '' })}
                                                    />
                                                </CCol>
                                                <CCol md="6">
                                                    <label><strong>Person</strong></label>
                                                    <Select
                                                        className="mb-3"
                                                        isClearable
                                                        placeholder="Optional"
                                                        options={personOptions}
                                                        value={personOptions.find(o => o.value === String(personId)) || null}
                                                        onChange={(opt) => this.setState({ personId: opt ? opt.value : '' })}
                                                    />
                                                </CCol>
                                            </CRow>

                                            <label><strong>Due Date</strong></label>
                                            <CInput
                                                className="mb-3"
                                                type="date"
                                                value={dueDate}
                                                onChange={(e) => this.setState({ dueDate: e.target.value })}
                                            />

                                            <label><strong>Comments</strong></label>
                                            {comments.length > 0 && (
                                                <ul style={{ paddingLeft: '20px' }}>
                                                    {comments.map((c, i) => (
                                                        <li key={'comment-' + i} style={{ marginBottom: '4px' }}>
                                                            {c.comment}
                                                            <CButton color="danger" size="sm" style={{ marginLeft: '8px' }} onClick={() => this.removeComment(i)}>✕</CButton>
                                                        </li>
                                                    ))}
                                                </ul>
                                            )}
                                            <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
                                                <CInput
                                                    placeholder="Add a comment"
                                                    value={newComment}
                                                    onChange={(e) => this.setState({ newComment: e.target.value })}
                                                    onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); this.addComment(); } }}
                                                />
                                                <CButton color="info" onClick={this.addComment}>+ Add</CButton>
                                            </div>

                                            <hr />
                                            <CRow>
                                                <CCol xs="6">
                                                    <CButton color="success" className="px-4" type="submit">CREATE</CButton>
                                                </CCol>
                                                <CCol xs="6" className="text-right">
                                                    <CButton color="danger" className="px-4" onClick={this.resetForm}>Reset</CButton>
                                                </CCol>
                                            </CRow>
                                        </CForm>
                                    </CCardBody>
                                </CCard>
                            </CCardGroup>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default CreateAction;
